import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Beyond Balancing- How Upmaps Were Used To Avoid Disaster! - Bryan Stillwell, Akamai Technologies","description":"","frontmatter":{"title":"Beyond Balancing- How Upmaps Were Used To Avoid Disaster! - Bryan Stillwell, Akamai Technologies","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Upmap","Distributed Storage","Hardware Failure","Data Distribution"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Beyond_Balancing_-_How_Upmaps_Were_Used_To_Avoid_Disaster_-_Bryan_Stillwell_Akamai_Technologies.md","filePath":"posts/2025/Beyond_Balancing_-_How_Upmaps_Were_Used_To_Avoid_Disaster_-_Bryan_Stillwell_Akamai_Technologies.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Beyond_Balancing_-_How_Upmaps_Were_Used_To_Avoid_Disaster_-_Bryan_Stillwell_Akamai_Technologies.md"};function t(s,e,_,n,p,d){return l(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-技术会议纪要" tabindex="-1">Ceph 技术会议纪要 <a class="header-anchor" href="#ceph-技术会议纪要" aria-label="Permalink to &quot;Ceph 技术会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li>主讲人：Bryan Stillwell（原 Okami 工程师，现 Clyo Communications 高级 SE 工程师）</li><li>主题：利用 upmap 解决硬件故障导致的数据分布问题</li><li>背景：Ceph 集群中因 NVMe retimer 卡硬件缺陷引发的 OSD 异常问题</li></ul><h4 id="会议关键内容总结" tabindex="-1">会议关键内容总结 <a class="header-anchor" href="#会议关键内容总结" aria-label="Permalink to &quot;会议关键内容总结&quot;">​</a></h4><h4 id="_1-问题背景-硬件-定时炸弹" tabindex="-1">1. 问题背景：硬件“定时炸弹” <a class="header-anchor" href="#_1-问题背景-硬件-定时炸弹" aria-label="Permalink to &quot;1. 问题背景：硬件“定时炸弹”&quot;">​</a></h4><ul><li>现象：内核升级后，多台服务器的 NVMe OSD 在重启时批量消失，集中在特定插槽（如 slot 4-7）。</li><li>硬件调查：部分 NVMe 盘通过 retimer 卡连接主板，设计缺陷导致启动时电压过高烧毁，影响 PCIe 16x 插槽的 OSD。</li><li>风险：数据中心断电可能导致大量 retimer 卡损坏，PG 因副本不足进入阻塞状态。</li></ul><h4 id="_2-解决方案-ceph-upmap-技术" tabindex="-1">2. 解决方案：Ceph upmap 技术 <a class="header-anchor" href="#_2-解决方案-ceph-upmap-技术" aria-label="Permalink to &quot;2. 解决方案：Ceph upmap 技术&quot;">​</a></h4><ul><li>upmap 简介：在 CRUSH 算法计算后手动调整 PG 的 OSD 分布，用于平衡数据分布、修复异常 PG。</li><li>应用场景：规避 retimer 卡风险，通过 <code>ceph osd pg-upmap-items</code> 命令替换高危 OSD。</li><li>工具开发：编写 <code>retimer_upmap</code> 脚本自动化处理，动态调整 PG 分布。</li><li>验证方法：使用 <code>ceph osd ok-to-stop</code> 命令验证 retimer OSD 停机是否安全。</li></ul><h4 id="_3-upmap-的其他应用场景" tabindex="-1">3. upmap 的其他应用场景 <a class="header-anchor" href="#_3-upmap-的其他应用场景" aria-label="Permalink to &quot;3. upmap 的其他应用场景&quot;">​</a></h4><ol><li>集群扩容：禁用 balancer → 添加新 OSD → 手动 upmap 迁移数据 → 重新启用 balancer。</li><li>快速恢复：将故障 OSD 的 PG 分散到全集群，利用多盘并行恢复加速。</li><li>存储后端迁移：如 filestore → bluestore 或未来 bluestore → seastore 的转换。</li><li>热点缓解：将高负载 OSD 的 Primary PG 分散到其他 OSD。</li><li>故障域迁移：从 host-based 切换至 rack-based 故障域时预分配 PG 位置。</li></ol><h4 id="_4-讨论与问答" tabindex="-1">4. 讨论与问答 <a class="header-anchor" href="#_4-讨论与问答" aria-label="Permalink to &quot;4. 讨论与问答&quot;">​</a></h4><ul><li>Q：OSD 编号是否全局有序？ <ul><li>A：实际无序，通过 Ansible 脚本动态生成 retimer OSD 列表并存储为 JSON。</li></ul></li><li>其他用例：开发者提到可用 upmap 对集群进行压力测试。</li></ul><h4 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h4><ol><li>短期：在受影响集群中部署 <code>retimer_upmap</code> 工具，优先处理含多个 retimer OSD 的 PG。</li><li>长期：逐步更换所有有缺陷的 retimer 卡，同步监控硬件厂商的固件更新。</li><li>最佳实践：定期备份 upmap 配置（OSD 重启可能导致映射丢失）。</li></ol>',14)])])}const c=a(r,[["render",t]]);export{m as __pageData,c as default};
